import (
	"fmt"
	"strconv"
)

func phraseed02cd0805872c6dc539a79f13857bcae5921c4b2ff964f4091e2a4a4e97246a(state *State, args []string) error {
	const (
		phrase    = "the result is {value:number}"
		zeroWord  = "no"
		wantArgs  = 1
		valueSlot = 0
	)

	if len(args) != wantArgs {
		return fmt.Errorf("%s: want %d argument, got %d", phrase, wantArgs, len(args))
	}

	raw := args[valueSlot]

	expected := 0
	if raw != zeroWord {
		parsed, err := strconv.Atoi(raw)
		if err != nil {
			return fmt.Errorf("%s: value %q is not a number: %w", phrase, raw, err)
		}
		expected = parsed
	}

	if !state.ResultSet {
		return fmt.Errorf("%s: no result was observed; double the number in a When before this Then", phrase)
	}

	// Compare only: state.Result holds the integer stdout of the `double`
	// command exactly as the When block observed it.
	if state.Result != expected {
		return fmt.Errorf("%s: want result %d, got %d", phrase, expected, state.Result)
	}

	return nil
}

package steps

import (
	"bytes"
	"context"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
	"time"
)

func phrasefd1683cb9efb040dcb9ff323bbe5d2d3e9f958d39b3e3e7eafcb136f94b8a9df(state *State, args []string) error {
	const (
		phrase   = "the number is doubled"
		wantArgs = 0
		// The suite's working directory is tests/calc, so the declared
		// "host root" of the `double` command is two levels up.
		hostRoot    = "../.."
		goBinary    = "go"
		runVerb     = "run"
		servicePath = "./services/calc"
		commandName = "double"
		runTimeout  = 2 * time.Minute
	)

	if len(args) != wantArgs {
		return fmt.Errorf("%s: want %d arguments, got %d", phrase, wantArgs, len(args))
	}

	if !state.NumberSet {
		return fmt.Errorf("%s: no number was supplied; state the number in a Given before this When", phrase)
	}

	ctx, cancel := context.WithTimeout(context.Background(), runTimeout)
	defer cancel()

	// Run the declared command as a process; the product does the doubling.
	value := strconv.Itoa(state.Number)
	cmd := exec.CommandContext(ctx, goBinary, runVerb, servicePath, commandName, value)
	cmd.Dir = hostRoot

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		return fmt.Errorf(
			"%s: %s %s %s %s %s in %s failed: %w: %s",
			phrase, goBinary, runVerb, servicePath, commandName, value, hostRoot, err,
			strings.TrimSpace(stderr.String()),
		)
	}

	// The declared response is the doubled integer and a newline on stdout.
	printed := strings.TrimSpace(stdout.String())
	doubled, err := strconv.Atoi(printed)
	if err != nil {
		return fmt.Errorf("%s: stdout %q is not an integer: %w", phrase, printed, err)
	}

	// Keep the observed stdout verbatim; the Then block compares it.
	state.Result = doubled
	state.ResultSet = true

	return nil
}

package steps

func Register(suite interface {
	Step(string, func(*State, []string) error)
}) {
	suite.Step("\\Athe number is ((?:[0-9]+|no))\\z", phrase7c963587b98a9c9fa59fafbd25518c3af0d8d428753a4c888f114e5a06aa3242)

	suite.Step("\\Athe number is doubled\\z", phrasefd1683cb9efb040dcb9ff323bbe5d2d3e9f958d39b3e3e7eafcb136f94b8a9df)

	suite.Step("\\Athe result is ((?:[0-9]+|no))\\z", phraseed02cd0805872c6dc539a79f13857bcae5921c4b2ff964f4091e2a4a4e97246a)
}

package steps

type State struct {
	// Number is the integer argument the next `double` command run receives.
	Number int
	// NumberSet records that a Given supplied Number, so the When can
	// refuse to run `double` with an unstated operand.
	NumberSet bool
	// Result is the integer the `double` command printed on stdout, kept
	// exactly as observed so the Then block only compares.
	Result int
	// ResultSet records that the `double` command ran and its stdout was
	// read, so the Then can refuse to compare an unobserved result.
	ResultSet bool
}
